import { Button } from "@/components/ui/button"
import { Label } from "@/components/ui/label"
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group"
import { 
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { ChevronRight } from "lucide-react"
import { useState } from "react"
import { useRouter } from "next/navigation"

export function OnboardingQuestionnaire() {
  const router = useRouter()
  const [step, setStep] = useState(1)
  const [answers, setAnswers] = useState({
    experience: "",
    riskTolerance: "",
    preferredSports: "",
    preferredBetTypes: "",
    timeCommitment: "",
  })

  const handleAnswerChange = (field: string, value: string) => {
    setAnswers(prev => ({ ...prev, [field]: value }))
  }

  const handleNext = async () => {
    if (step < 5) {
      setStep(step + 1)
    } else {
      // Send answers to API for processing
      try {
        const response = await fetch("/api/analyze-preferences", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
          },
          body: JSON.stringify(answers),
        })
        
        if (!response.ok) throw new Error("Failed to process preferences")
        
        const data = await response.json()
        
        // Redirect to personalized recommendations
        router.push(`/recommendations?id=${data.recommendationId}`)
      } catch (error) {
        console.error("Error processing preferences:", error)
        // Handle error appropriately
      }
    }
  }

  const handleBack = () => {
    if (step > 1) {
      setStep(step - 1)
    }
  }

  return (
    <div className="space-y-8">
      {step === 1 && (
        <div className="space-y-4">
          <h2 className="text-xl font-semibold">Betting Experience</h2>
          <RadioGroup
            defaultValue={answers.experience}
            onValueChange={(value) => handleAnswerChange("experience", value)}
          >
            <div className="space-y-3">
              <div className="flex items-center space-x-2">
                <RadioGroupItem value="beginner" id="beginner" />
                <Label htmlFor="beginner">I&apos;m new to betting</Label>
              </div>
              <div className="flex items-center space-x-2">
                <RadioGroupItem value="intermediate" id="intermediate" />
                <Label htmlFor="intermediate">I have some betting experience</Label>
              </div>
              <div className="flex items-center space-x-2">
                <RadioGroupItem value="advanced" id="advanced" />
                <Label htmlFor="advanced">I&apos;m an experienced bettor</Label>
              </div>
            </div>
          </RadioGroup>
        </div>
      )}

      {step === 2 && (
        <div className="space-y-4">
          <h2 className="text-xl font-semibold">Risk Tolerance</h2>
          <RadioGroup
            defaultValue={answers.riskTolerance}
            onValueChange={(value) => handleAnswerChange("riskTolerance", value)}
          >
            <div className="space-y-3">
              <div className="flex items-center space-x-2">
                <RadioGroupItem value="conservative" id="conservative" />
                <Label htmlFor="conservative">Conservative - Lower risk, steady returns</Label>
              </div>
              <div className="flex items-center space-x-2">
                <RadioGroupItem value="moderate" id="moderate" />
                <Label htmlFor="moderate">Moderate - Balanced risk and reward</Label>
              </div>
              <div className="flex items-center space-x-2">
                <RadioGroupItem value="aggressive" id="aggressive" />
                <Label htmlFor="aggressive">Aggressive - Higher risk, higher potential returns</Label>
              </div>
            </div>
          </RadioGroup>
        </div>
      )}

      {step === 3 && (
        <div className="space-y-4">
          <h2 className="text-xl font-semibold">Preferred Sports</h2>
          <Select
            value={answers.preferredSports[0]}
            onValueChange={(value) => handleAnswerChange("preferredSports", value)}
          >
            <SelectTrigger>
              <SelectValue placeholder="Select your favorite sport" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="football">Football (NFL)</SelectItem>
              <SelectItem value="basketball">Basketball (NBA)</SelectItem>
              <SelectItem value="baseball">Baseball (MLB)</SelectItem>
              <SelectItem value="hockey">Hockey (NHL)</SelectItem>
              <SelectItem value="soccer">Soccer</SelectItem>
              <SelectItem value="mma">MMA/UFC</SelectItem>
              <SelectItem value="esports">Esports</SelectItem>
            </SelectContent>
          </Select>
        </div>
      )}

      {step === 4 && (
        <div className="space-y-4">
          <h2 className="text-xl font-semibold">Preferred Bet Types</h2>
          <RadioGroup
            defaultValue={answers.preferredBetTypes as string}
            onValueChange={(value) => handleAnswerChange("preferredBetTypes", value)}
          >
            <div className="space-y-3">
              <div className="flex items-center space-x-2">
                <RadioGroupItem value="simple" id="simple" />
                <Label htmlFor="simple">Simple bets (Moneyline, Over/Under)</Label>
              </div>
              <div className="flex items-center space-x-2">
                <RadioGroupItem value="moderate" id="moderate-bets" />
                <Label htmlFor="moderate-bets">Moderate (Point Spreads, Props)</Label>
              </div>
              <div className="flex items-center space-x-2">
                <RadioGroupItem value="complex" id="complex" />
                <Label htmlFor="complex">Complex (Parlays, Teasers, Live betting)</Label>
              </div>
            </div>
          </RadioGroup>
        </div>
      )}

      {step === 5 && (
        <div className="space-y-4">
          <h2 className="text-xl font-semibold">Time Commitment</h2>
          <RadioGroup
            defaultValue={answers.timeCommitment}
            onValueChange={(value) => handleAnswerChange("timeCommitment", value)}
          >
            <div className="space-y-3">
              <div className="flex items-center space-x-2">
                <RadioGroupItem value="casual" id="casual" />
                <Label htmlFor="casual">Casual - Few bets per month</Label>
              </div>
              <div className="flex items-center space-x-2">
                <RadioGroupItem value="regular" id="regular" />
                <Label htmlFor="regular">Regular - Weekly betting</Label>
              </div>
              <div className="flex items-center space-x-2">
                <RadioGroupItem value="active" id="active" />
                <Label htmlFor="active">Active - Daily betting</Label>
              </div>
            </div>
          </RadioGroup>
        </div>
      )}

      <div className="flex justify-between pt-6">
        <Button
          variant="outline"
          onClick={handleBack}
          disabled={step === 1}
        >
          Back
        </Button>
        <Button
          onClick={handleNext}
          className="gap-2"
        >
          {step === 5 ? "Get Recommendations" : "Next"}
          <ChevronRight className="h-4 w-4" />
        </Button>
      </div>

      <div className="pt-4">
        <div className="flex justify-between text-sm text-muted-foreground">
          <span>Question {step} of 5</span>
          <span>{Math.round((step / 5) * 100)}% Complete</span>
        </div>
        <div className="mt-2 h-2 w-full rounded-full bg-muted">
          <div
            className="h-2 rounded-full bg-primary transition-all duration-300"
            style={{ width: `${(step / 5) * 100}%` }}
          />
        </div>
      </div>
    </div>
  )
}